\sum_{i=1}^k \tau_{i-1}x^{(i)}, \qquad
\bar z^{(k)}_\avg = \frac{1}{\sum_{i=1}^k \tau_{i-1}}
\sum_{i=1}^k \tau_{i-1} \bar z^{(i)}
\]
