  \label{e-ls-conv} \\ 
&\leq \frac{1}{k \tau_\mathrm{min}}
  \big(d_\primal(x,x^{(0)}) + \frac{1}{2\beta} \|z-z^{(0)}\|^2\big)
  \label{e-ls-conv-1/k}
\end{align}
for all $x \in \dom f \cap \dom \phi_\primal$ and all $z$.
This holds for any choice of $\delta \in (0,1]$ in~\eqref{e-ls-cond}.
